using Ritm.Data.Entities;

namespace Ritm.Data;

// Все стартовые данные в одном месте: упражнения и шаблоны программ (UserId = null).
public static class SeedData
{
    public record Result(List<Exercise> Exercises, List<WorkoutProgram> Programs);

    public static Result Create()
    {
        var exercises = new List<Exercise>
        {
            new() { Name = "Присед со штангой", MuscleGroup = "Ноги", Equipment = "Штанга", Description = "Штанга лежит на верхней части спины, стопы на ширине плеч. Садись, отводя таз назад, пока бёдра не станут параллельны полу, и вставай, не округляя спину." },
            new() { Name = "Жим штанги лёжа", MuscleGroup = "Грудь", Equipment = "Штанга", Description = "Лёжа на скамье, опусти штангу к середине груди и выжми вверх. Лопатки сведены и прижаты к скамье, стопы стоят на полу." },
            new() { Name = "Становая тяга", MuscleGroup = "Спина", Equipment = "Штанга", Description = "Штанга лежит у голеней, спина прямая. Вставай, разгибая бёдра и колени одновременно, и верни штангу на пол под контролем." },
            new() { Name = "Жим штанги стоя", MuscleGroup = "Плечи", Equipment = "Штанга", Description = "Штанга у плеч, корпус напряжён. Выжми её над головой до выпрямления рук и медленно опусти обратно." },
            new() { Name = "Тяга штанги в наклоне", MuscleGroup = "Спина", Equipment = "Штанга", Description = "Наклони корпус почти параллельно полу, спина прямая. Тяни штангу к низу живота, сводя лопатки, и опускай без рывка." },
            new() { Name = "Румынская тяга", MuscleGroup = "Ноги", Equipment = "Штанга", Description = "Ноги слегка согнуты, штанга скользит вдоль бёдер. Отводи таз назад, пока не почувствуешь растяжение задней поверхности бедра, и возвращайся вверх." },
            new() { Name = "Жим ногами", MuscleGroup = "Ноги", Equipment = "Тренажёр", Description = "Сядь в тренажёр, стопы на платформе на ширине плеч. Опускай платформу до угла в коленях около 90 градусов и выжимай обратно, не распрямляя колени до конца." },
            new() { Name = "Тяга верхнего блока", MuscleGroup = "Спина", Equipment = "Блок", Description = "Возьмись за рукоять хватом чуть шире плеч. Тяни её к верху груди, сводя лопатки, и медленно возвращай вверх." },
            new() { Name = "Тяга нижнего блока", MuscleGroup = "Спина", Equipment = "Блок", Description = "Сядь с прямой спиной, ноги упираются в платформу. Тяни рукоять к животу, сводя лопатки, без раскачки корпусом." },
            new() { Name = "Жим в тренажёре от груди", MuscleGroup = "Грудь", Equipment = "Тренажёр", Description = "Отрегулируй сиденье так, чтобы рукояти были на уровне середины груди. Выжимай их вперёд до выпрямления рук и возвращай контролируемо." },
            new() { Name = "Разгибание ног в тренажёре", MuscleGroup = "Ноги", Equipment = "Тренажёр", Description = "Сядь, валик лежит на голенях у лодыжек. Разгибай колени до конца и медленно опускай, без рывков." },
            new() { Name = "Сгибание ног лёжа", MuscleGroup = "Ноги", Equipment = "Тренажёр", Description = "Лёжа на животе, валик на голенях. Сгибай ноги к ягодицам и медленно возвращай, не отрывая таз от скамьи." },
            new() { Name = "Разводка в кроссовере", MuscleGroup = "Грудь", Equipment = "Блок", Description = "Встань между блоками, рукояти на уровне груди. Своди руки перед собой дугой с лёгким сгибом в локтях и медленно разводи обратно." },
            new() { Name = "Разгибание рук на блоке", MuscleGroup = "Руки", Equipment = "Блок", Description = "Локти прижаты к корпусу. Разгибай руки вниз до конца и медленно возвращай рукоять к груди." },
            new() { Name = "Сгибание рук со штангой", MuscleGroup = "Руки", Equipment = "Штанга", Description = "Стоя, держи штангу хватом снизу. Сгибай руки, не раскачивая корпус, и опускай штангу медленно." },
            new() { Name = "Жим гантелей лёжа", MuscleGroup = "Грудь", Equipment = "Гантели", Description = "Лёжа на скамье (или на полу), опускай гантели до уровня груди и выжимай вверх. Локти не разводи шире плеч." },
            new() { Name = "Жим гантелей сидя", MuscleGroup = "Плечи", Equipment = "Гантели", Description = "Сядь со спинкой, гантели у плеч. Выжми их вверх до выпрямления рук и опусти без ударов." },
            new() { Name = "Тяга гантели в наклоне", MuscleGroup = "Спина", Equipment = "Гантели", Description = "Одной рукой и коленом упрись в скамью, спина прямая. Тяни гантель к поясу, не разворачивая корпус, и опускай вниз." },
            new() { Name = "Гоблет-присед", MuscleGroup = "Ноги", Equipment = "Гантели", Description = "Держи гантель у груди двумя руками. Приседай с прямой спиной, колени идут по линии носков, потом вставай." },
            new() { Name = "Выпады с гантелями", MuscleGroup = "Ноги", Equipment = "Гантели", Description = "Сделай шаг вперёд и опустись, пока оба колена не согнутся примерно до прямого угла. Оттолкнись передней ногой и вернись назад." },
            new() { Name = "Румынская тяга с гантелями", MuscleGroup = "Ноги", Equipment = "Гантели", Description = "Гантели вдоль ног, колени чуть согнуты. Отводи таз назад, пока не почувствуешь растяжение под коленями, и возвращайся вверх." },
            new() { Name = "Подъём гантелей в стороны", MuscleGroup = "Плечи", Equipment = "Гантели", Description = "Стоя, подними гантели в стороны до уровня плеч, локти слегка согнуты. Опускай медленно, без рывков и раскачки корпуса." },
            new() { Name = "Сгибание рук с гантелями", MuscleGroup = "Руки", Equipment = "Гантели", Description = "Стоя, держи гантели вдоль корпуса ладонями вперёд. Сгибай руки, не отрывая локти от корпуса, и медленно опускай." },
            new() { Name = "Французский жим с гантелью", MuscleGroup = "Руки", Equipment = "Гантели", Description = "Лёжа, держи гантель двумя руками над собой. Сгибай локти, опуская её за голову, и разгибай обратно, не разводя локти." },
            new() { Name = "Отжимания", MuscleGroup = "Грудь", Equipment = "Свой вес", Description = "Руки чуть шире плеч, тело держится прямой линией. Опускайся почти до пола и отжимайся вверх. Если трудно, начни с колен." },
            new() { Name = "Подтягивания", MuscleGroup = "Спина", Equipment = "Турник", Description = "Хват чуть шире плеч, начни из виса. Подтянись до подбородка над перекладиной и опустись под контролем. Новичку помогает резинка." },
            new() { Name = "Приседания с собственным весом", MuscleGroup = "Ноги", Equipment = "Свой вес", Description = "Стопы на ширине плеч, руки перед собой. Садись, отводя таз назад, до параллели бёдер с полом и вставай, не округляя спину." },
            new() { Name = "Ягодичный мостик", MuscleGroup = "Ноги", Equipment = "Свой вес", Description = "Лёжа на спине, стопы стоят близко к тазу. Поднимай таз, сжимая ягодицы, до прямой линии от плеч до коленей, и медленно опускай." },
            new() { Name = "Планка", MuscleGroup = "Пресс", Equipment = "Свой вес", Description = "Упор на предплечья, тело прямой линией. Держи живот и ягодицы напряжёнными, не прогибай поясницу. Держи столько секунд, сколько указано." },
            new() { Name = "Скручивания", MuscleGroup = "Пресс", Equipment = "Свой вес", Description = "Лёжа на спине, колени согнуты. Подними плечи от пола, напрягая пресс, и медленно вернись, не дёргая шею руками." },
            new() { Name = "Обратные отжимания от стула", MuscleGroup = "Руки", Equipment = "Свой вес", Description = "Обопрись руками о край стула позади себя, ноги вытянуты. Сгибай локти назад, пока плечи не опустятся до уровня локтей, и выжимай вверх." },
            new() { Name = "Супермен", MuscleGroup = "Спина", Equipment = "Свой вес", Description = "Лёжа на животе, руки вытянуты вперёд. Одновременно приподними руки и ноги от пола, задержись на секунду и опустись." },
        };
        var byName = exercises.ToDictionary(e => e.Name);

        (string, int, int, int) X(string name) => (name, 3, 8, 12);
        (string, int, int, int) Core(string name, int min, int max) => (name, 3, min, max);

        ProgramDay Day(int number, string title, params (string name, int sets, int min, int max)[] items) => new()
        {
            DayNumber = number,
            Title = title,
            Exercises = items.Select((it, i) => new ProgramExercise
            {
                Exercise = byName[it.name],
                Sets = it.sets,
                RepsMin = it.min,
                RepsMax = it.max,
                Position = i + 1
            }).ToList()
        };

        WorkoutProgram Prog(string name, string level, int days, string place, params ProgramDay[] d) => new()
        {
            Name = name, Level = level, DaysPerWeek = days, Place = place, Days = d.ToList()
        };

        var programs = new List<WorkoutProgram>
        {
            Prog("Фулбади на 2 дня · зал", "beginner", 2, "gym",
                Day(1, "Всё тело А", X("Присед со штангой"), X("Жим штанги лёжа"), X("Тяга верхнего блока"), Core("Планка", 30, 45)),
                Day(2, "Всё тело Б", X("Румынская тяга"), X("Жим гантелей сидя"), X("Тяга нижнего блока"), Core("Скручивания", 12, 15))),

            Prog("Фулбади на 3 дня · зал", "beginner", 3, "gym",
                Day(1, "Всё тело А", X("Присед со штангой"), X("Жим штанги лёжа"), X("Тяга верхнего блока"), Core("Планка", 30, 45)),
                Day(2, "Всё тело Б", X("Румынская тяга"), X("Жим гантелей сидя"), X("Тяга нижнего блока"), Core("Скручивания", 12, 15)),
                Day(3, "Всё тело В", X("Жим ногами"), X("Жим гантелей лёжа"), X("Тяга гантели в наклоне"), Core("Планка", 30, 45))),

            Prog("Верх/низ на 4 дня · зал", "intermediate", 4, "gym",
                Day(1, "Верх А", X("Жим штанги лёжа"), X("Тяга штанги в наклоне"), X("Жим гантелей сидя"), X("Сгибание рук со штангой"), X("Разгибание рук на блоке")),
                Day(2, "Низ А", X("Присед со штангой"), X("Румынская тяга"), X("Жим ногами"), X("Сгибание ног лёжа"), Core("Планка", 30, 45)),
                Day(3, "Верх Б", X("Жим гантелей лёжа"), X("Тяга верхнего блока"), X("Подъём гантелей в стороны"), X("Тяга нижнего блока"), X("Французский жим с гантелью")),
                Day(4, "Низ Б", X("Выпады с гантелями"), X("Разгибание ног в тренажёре"), X("Ягодичный мостик"), X("Жим ногами"), Core("Скручивания", 12, 15))),

            Prog("Фулбади на 2 дня · дома с гантелями", "beginner", 2, "home-dumbbells",
                Day(1, "Всё тело А", X("Гоблет-присед"), X("Жим гантелей лёжа"), X("Тяга гантели в наклоне"), Core("Планка", 30, 45)),
                Day(2, "Всё тело Б", X("Румынская тяга с гантелями"), X("Жим гантелей сидя"), X("Выпады с гантелями"), Core("Скручивания", 12, 15))),

            Prog("Фулбади на 3 дня · дома с гантелями", "beginner", 3, "home-dumbbells",
                Day(1, "Всё тело А", X("Гоблет-присед"), X("Жим гантелей лёжа"), X("Тяга гантели в наклоне"), Core("Планка", 30, 45)),
                Day(2, "Всё тело Б", X("Румынская тяга с гантелями"), X("Жим гантелей сидя"), X("Выпады с гантелями"), Core("Скручивания", 12, 15)),
                Day(3, "Всё тело В", X("Отжимания"), X("Подъём гантелей в стороны"), X("Сгибание рук с гантелями"), X("Ягодичный мостик"))),

            Prog("Фулбади на 2 дня · без инвентаря", "beginner", 2, "home-bodyweight",
                Day(1, "Всё тело А", X("Приседания с собственным весом"), X("Отжимания"), X("Супермен"), Core("Планка", 30, 45)),
                Day(2, "Всё тело Б", X("Ягодичный мостик"), X("Обратные отжимания от стула"), X("Супермен"), Core("Скручивания", 12, 15))),

            Prog("Фулбади на 3 дня · без инвентаря", "beginner", 3, "home-bodyweight",
                Day(1, "Всё тело А", X("Приседания с собственным весом"), X("Отжимания"), X("Супермен"), Core("Планка", 30, 45)),
                Day(2, "Всё тело Б", X("Ягодичный мостик"), X("Обратные отжимания от стула"), X("Супермен"), Core("Скручивания", 12, 15)),
                Day(3, "Всё тело В", X("Приседания с собственным весом"), X("Отжимания"), X("Ягодичный мостик"), Core("Планка", 30, 45))),
        };

        return new Result(exercises, programs);
    }
}
